insert into public.drills (id, owner_id, source, area, category, title, seen_with, duration_min, difficulty, shot_type, equipment, text, scoring, needs_verification) values
('fade-and-draw', null, 'booklet', 'range', 'tee', 'Fade and Draw', 'Tom Lehman', 10, 5, 'Driver', '{"de":"10 Bälle, Alignment Sticks"}'::jsonb, '{"de":{"setup":"Je ein Schläger/Stick 0,5 m vor und hinter dem Abschlagpunkt auf der Ziellinie; Stick oder geschlossener Schirm ca. 10 m voraus auf der Linie. Zwei Punkte als Korridor, 30 m breit.","goal":"Möglichst viele Bälle in den Korridor; Ball muss je nach Kurve links/rechts am Stick vorbei und zurück ins Ziel drehen.","procedure":"Aufteen; abwechselnd Fade (links-rechts für RH) und Draw (rechts-links). 10 Bälle: 5 Fades, 5 Draws.","scoring_note":"Bälle im Korridor: 36-27: 2 | 26-12: 4 | 11-0: 7"},"en":null}'::jsonb, '{"type":"count_higher_better","lower_is_better":false,"perfect":10,"bands":[{"hcp_hi":36,"hcp_lo":27,"target":2},{"hcp_hi":26,"hcp_lo":12,"target":4},{"hcp_hi":11,"hcp_lo":0,"target":7}]}'::jsonb, 'HCP-Spalte beginnt laut Foto bei 36 statt 54'),
('short-aims', null, 'booklet', 'range', 'tee', 'Short Aims', 'Davis Love', 15, 4, 'Driver', '{"de":"20 Bälle, Laser, Stoppuhr"}'::jsonb, '{"de":{"setup":"Ziele auf 100, 125, 150 und 175 m abmessen (oder Zielgrüns/Entfernungsmarkierungen nutzen).","goal":"Alle 4 Distanzen durchspielen; nach 15 Min stoppen und erreichte Station notieren.","procedure":"Mit dem Driver carry aufs 100-m-Ziel. Treffer = Landung im 10-m-Radius, Ausrollen egal. Nach 3 Treffern zur nächsten Distanz.","scoring_note":"Stationen in 15 Min: 54-27: 2 | 26-12: 3 | 11-0: 4"},"en":null}'::jsonb, '{"type":"stations_reached","lower_is_better":false,"perfect":4,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":2},{"hcp_hi":26,"hcp_lo":12,"target":3},{"hcp_hi":11,"hcp_lo":0,"target":4}]}'::jsonb, null),
('14-fairways', null, 'booklet', 'range', 'tee', '14 Fairways', 'Jim Furyk', 25, 2, 'Driver', '{"de":"28 Bälle, Laser"}'::jsonb, '{"de":{"setup":"Zwei Punkte (Zielgrüns, Fahnen, Bäume) als Korridor, Abstand ca. 30 m.","goal":"Möglichst viele Bälle inkl. Ausrollen im Korridor. Gezählt werden nur die Drives; Eisen dient dem Rhythmus.","procedure":"Abwechselnd 1 Ball Eisen 7, dann 1 Ball Driver, ähnliches Tempo/Rhythmus. 14 Bälle Driver + 14 Bälle Eisen.","scoring_note":"Drives im Korridor (min. 150 m): 54-27: 4 | 26-12: 7 | 11-0: 11"},"en":null}'::jsonb, '{"type":"count_higher_better","lower_is_better":false,"perfect":14,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":4},{"hcp_hi":26,"hcp_lo":12,"target":7},{"hcp_hi":11,"hcp_lo":0,"target":11}]}'::jsonb, null),
('hit-three-greens', null, 'booklet', 'range', 'approach', 'Hit Three Greens', null, 20, 4, 'Eisen', '{"de":"9 Bälle, Laser"}'::jsonb, '{"de":{"setup":"3 Ziele, mit unterschiedlichen Schlägern carry erreichbar, platztypische Distanzen (z. B. 100/130/160 m). Ab 190 m Aufteen erlaubt.","goal":"Möglichst oft das Grün treffen; ohne Zielgrün Radius von ca. 10 % der Entfernung.","procedure":"9 Bälle auf 3 Ziele, abwechselnd; mit kürzestem Ziel beginnen; vor jedem Schlag Pre-Shot-Routine.","scoring_note":"Punkte (kurz 2 / mittel 3 / weit 4 je Treffer): 54-27: 9 | 26-14: 14 | 11-0: 20"},"en":null}'::jsonb, '{"type":"count_higher_better","lower_is_better":false,"perfect":27,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":9},{"hcp_hi":26,"hcp_lo":14,"target":14},{"hcp_hi":11,"hcp_lo":0,"target":20}]}'::jsonb, 'Mittlere Stufe laut Foto 26-14'),
('nine-drives', null, 'booklet', 'range', 'tee', 'Nine Drives', 'Martina Eberl-Ellis', 15, 4, 'Driver', '{"de":"9 Bälle, Laser"}'::jsonb, '{"de":{"setup":"Zwei Punkte als Korridor, Abstand ca. 30 m.","goal":"Möglichst viele Bälle inkl. Ausrollen im Korridor (Mindestlänge 150 m).","procedure":"9 Bälle; je ein Loch des Heimatclubs vorstellen (ohne Par 3); Driver oder Fairwayholz; volle Routine, ein Abschlag pro Loch.","scoring_note":"Bälle im Korridor: 54-36: 3 | 35-27: 4 | 26-19: 5 | 18-12: 6 | 11-5: 7 | 4-0: 8"},"en":null}'::jsonb, '{"type":"count_higher_better","lower_is_better":false,"perfect":9,"bands":[{"hcp_hi":54,"hcp_lo":36,"target":3},{"hcp_hi":35,"hcp_lo":27,"target":4},{"hcp_hi":26,"hcp_lo":19,"target":5},{"hcp_hi":18,"hcp_lo":12,"target":6},{"hcp_hi":11,"hcp_lo":5,"target":7},{"hcp_hi":4,"hcp_lo":0,"target":8}]}'::jsonb, null),
('five-different-clubs', null, 'booklet', 'pitching', 'short', 'Five Different Clubs', null, 25, 5, 'Chip & Pitch', '{"de":"20 Bälle"}'::jsonb, '{"de":{"setup":"4 Stationen in ca. 10, 15, 20 und 25 m zur Fahne; ggf. verschiedene Fahnenpositionen.","goal":"Möglichst viele Bälle in den vorgegebenen Radius.","procedure":"Von jeder Station 5 Bälle mit 5 unterschiedlichen, vorher gewählten Schlägern (z. B. 2 Wedges, Eisen 7-9, Hybrid).","scoring_note":"1 Punkt je Ball im Radius (max. 20, 10 = gut). Radius: 54-27: Grün | 26-19: <6 m | 18-12: <4 m | 11-5: <3 m | 4-0: <1,5 m"},"en":null}'::jsonb, '{"type":"radius_by_band","lower_is_better":false,"perfect":20,"balls":20,"pass_hits":10,"pass_assumed":false,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":"green"},{"hcp_hi":26,"hcp_lo":19,"target":{"radius_m":6}},{"hcp_hi":18,"hcp_lo":12,"target":{"radius_m":4}},{"hcp_hi":11,"hcp_lo":5,"target":{"radius_m":3}},{"hcp_hi":4,"hcp_lo":0,"target":{"radius_m":1.5}}]}'::jsonb, 'Minutenangabe schwer lesbar'),
('attack-the-flag', null, 'booklet', 'pitching', 'short', 'Attack the Flag', null, 20, 4, 'Pitch', '{"de":"9 Bälle"}'::jsonb, '{"de":{"setup":"3 Positionen in 20, 30 und 40 m zur Fahne. Spiellinie soll hohes Anspiel erfordern (Rough, Bunker); alternativ Bag ca. 10 m vor der Fahne als Hindernis.","goal":"Möglichst viele Bälle im HCP-Radius; 1 Punkt pro Treffer.","procedure":"Mit einem oder mehreren Wedges 9 Bälle aus 3 Distanzen; Ball droppen; je 1 Ball in aufsteigender Entfernung, dann zurück auf 20 m.","scoring_note":"Radius: 54-27: Grün | 26-19: <7 m | 18-12: <5 m | 11-5: <3 m | 4-0: <2 m"},"en":null}'::jsonb, '{"type":"radius_by_band","lower_is_better":false,"perfect":9,"balls":9,"pass_hits":5,"pass_assumed":true,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":"green"},{"hcp_hi":26,"hcp_lo":19,"target":{"radius_m":7}},{"hcp_hi":18,"hcp_lo":12,"target":{"radius_m":5}},{"hcp_hi":11,"hcp_lo":5,"target":{"radius_m":3}},{"hcp_hi":4,"hcp_lo":0,"target":{"radius_m":2}}]}'::jsonb, 'Minuten und Anspruch schwer lesbar'),
('four-stations', null, 'booklet', 'pitching', 'short', 'Four Stations', 'Bernd Ritthammer', 10, 5, 'Chip & Pitch', '{"de":"4 Bälle"}'::jsonb, '{"de":{"setup":"4 Stationen vor einer Fahne: 1. Ball auf dem Vorgrün, 3 weitere auf einer Linie zur Fahne mit je 5 m Abstand (5/10/15 m). Bälle droppen.","goal":"Nah an die Fahne: ≤1 Schlägerlänge (90 cm) = 2 P | ≤3 Schlägerlängen = 1 P | eingelocht = 3 P.","procedure":"4 Bälle von 4 Stationen mit passenden Schlägern; danach neue Spiellinie; insgesamt 3 Durchgänge.","scoring_note":"Punkte: 54-36: 6 | 35-27: 10 | 26-19: 14 | 18-12: 16 | 11-5: 21 | 4-0: 24"},"en":null}'::jsonb, '{"type":"points_per_ball","lower_is_better":false,"perfect":36,"buttons":[3,2,1,0],"bands":[{"hcp_hi":54,"hcp_lo":36,"target":6},{"hcp_hi":35,"hcp_lo":27,"target":10},{"hcp_hi":26,"hcp_lo":19,"target":14},{"hcp_hi":18,"hcp_lo":12,"target":16},{"hcp_hi":11,"hcp_lo":5,"target":21},{"hcp_hi":4,"hcp_lo":0,"target":24}]}'::jsonb, 'Minutenangabe schwer lesbar'),
('sandy-par', null, 'booklet', 'bunker', 'short', 'Sandy Par', null, 10, 5, 'Sandschlag', '{"de":"1 Ball"}'::jsonb, '{"de":{"setup":"5 Löcher in 3-10 m Entfernung; bei zu wenigen Löchern Lage im Bunker variieren.","goal":"Möglichst wenige Schläge; so oft wie möglich Up & Down aus dem Bunker.","procedure":"Bunkerschlag auf eine der 5 Fahnen, dann mit Putter zu Ende spielen, Score notieren. 5 Bunkerschläge.","scoring_note":"Schläge gesamt: 54-36: 20 | 35-27: 17 | 26-19: 15 | 18-12: 13 | 11-5: 12 | 4-0: 10"},"en":null}'::jsonb, '{"type":"count_lower_better","lower_is_better":true,"perfect":5,"bands":[{"hcp_hi":54,"hcp_lo":36,"target":20},{"hcp_hi":35,"hcp_lo":27,"target":17},{"hcp_hi":26,"hcp_lo":19,"target":15},{"hcp_hi":18,"hcp_lo":12,"target":13},{"hcp_hi":11,"hcp_lo":5,"target":12},{"hcp_hi":4,"hcp_lo":0,"target":10}]}'::jsonb, 'Minutenangabe schwer lesbar'),
('hit-it-close', null, 'booklet', 'bunker', 'short', 'Hit It Close', 'Phil Mickelson', 10, 4, 'Sandschlag', '{"de":"5 Bälle"}'::jsonb, '{"de":{"setup":"Gut sichtbare Fahne, Schlag ca. 10 m; alternativ Ziel mit Alignment Stick oder Ball markieren.","goal":"Zielkreis 1 Schlägerlänge (90 cm) = 3 P | 3 Schlägerlängen = 2 P | Grün = 1 P | eingelocht = 5 P.","procedure":"5 Bälle; vor jedem Schlag volle Pre-Shot-Routine, dafür jeweils aus dem Bunker gehen.","scoring_note":"Punkte: 54-36: 3 | 35-27: 4 | 26-19: 5 | 18-12: 7 | 11-5: 9 | 4-0: 12"},"en":null}'::jsonb, '{"type":"points_per_ball","lower_is_better":false,"perfect":25,"buttons":[5,3,2,1,0],"bands":[{"hcp_hi":54,"hcp_lo":36,"target":3},{"hcp_hi":35,"hcp_lo":27,"target":4},{"hcp_hi":26,"hcp_lo":19,"target":5},{"hcp_hi":18,"hcp_lo":12,"target":7},{"hcp_hi":11,"hcp_lo":5,"target":9},{"hcp_hi":4,"hcp_lo":0,"target":12}]}'::jsonb, null),
('hit-the-spot', null, 'booklet', 'chipping', 'short', 'Hit the Spot', 'Tiger Woods', 10, 4, 'Chip', '{"de":"15 Bälle, 4 Schläger"}'::jsonb, '{"de":{"setup":"4 Schläger/Sticks quer zur Spiellinie bei 4, 6, 8 und 10 m (je ca. 2 m Abstand) = 3 Landezonen; alternativ Tees.","goal":"Ball muss in der Landezone aufkommen, Ausrollen egal; 1 Punkt pro Treffer.","procedure":"Je 1 Ball pro Landezone, kurz beginnend; nach der 3. Zone zurück zur 1. Insgesamt 15 Bälle (5 Durchgänge).","scoring_note":"Treffer: 54-36: 2 | 35-27: 4 | 26-19: 6 | 18-12: 9 | 11-5: 12 | 4-0: 15"},"en":null}'::jsonb, '{"type":"count_higher_better","lower_is_better":false,"perfect":15,"bands":[{"hcp_hi":54,"hcp_lo":36,"target":2},{"hcp_hi":35,"hcp_lo":27,"target":4},{"hcp_hi":26,"hcp_lo":19,"target":6},{"hcp_hi":18,"hcp_lo":12,"target":9},{"hcp_hi":11,"hcp_lo":5,"target":12},{"hcp_hi":4,"hcp_lo":0,"target":15}]}'::jsonb, 'Minutenangabe schwer lesbar'),
('chip-to-a-towel', null, 'booklet', 'chipping', 'short', 'Chip to a Towel', null, 15, 3, 'Chip', '{"de":"4 Bälle, Stoppuhr, Schlägertuch"}'::jsonb, '{"de":{"setup":"Schlägertuch (ca. 60×40 cm) aufs Grün oder Rechteck mit 4 Tees; Positionen in 2, 4, 5 und 6 m.","goal":"Möglichst schnell 8 Treffer; nach 15 Min Übung beenden.","procedure":"Je 1 Ball pro Position, Tuch im Flug treffen. Wenn alle 4 Positionen getroffen: neue Serie, Ball muss auf dem Tuch liegen bleiben, bis von allen 4 Positionen ein Treffer gelingt.","scoring_note":"Minuten bis 8 Treffer: 54-37: 15 | 36-27: 13 | 26-19: 12 | 18-12: 10 | 11-5: 8 | 4-0: 6 (sonst Trefferzahl notieren)"},"en":null}'::jsonb, '{"type":"time_lower_better","lower_is_better":true,"perfect":null,"bands":[{"hcp_hi":54,"hcp_lo":37,"target":15},{"hcp_hi":36,"hcp_lo":27,"target":13},{"hcp_hi":26,"hcp_lo":19,"target":12},{"hcp_hi":18,"hcp_lo":12,"target":10},{"hcp_hi":11,"hcp_lo":5,"target":8},{"hcp_hi":4,"hcp_lo":0,"target":6}]}'::jsonb, 'HCP-Stufen laut Foto 54-37 / 36-27'),
('worstball-chipping', null, 'booklet', 'chipping', 'short', 'Worstball Chipping', null, 20, 6, 'Chip', '{"de":"2 Bälle"}'::jsonb, '{"de":{"setup":"Mehrere Positionen in 6-12 m, von denen mind. 3 Löcher anspielbar sind; Startpositionen mit Tee markieren.","goal":"Mit möglichst wenigen Schlägen einlochen; Up & Down mit dem schlechteren Versuch.","procedure":"9 Situationen; pro Position 2 Bälle droppen und chippen, den weiter vom Loch entfernten wählen und nur diesen zu Ende putten.","scoring_note":"Schläge: 54-36: 33 | 35-27: 30 | 26-19: 27 | 18-12: 25 | 11-5: 22 | 4-0: 19"},"en":null}'::jsonb, '{"type":"count_lower_better","lower_is_better":true,"perfect":9,"bands":[{"hcp_hi":54,"hcp_lo":36,"target":33},{"hcp_hi":35,"hcp_lo":27,"target":30},{"hcp_hi":26,"hcp_lo":19,"target":27},{"hcp_hi":18,"hcp_lo":12,"target":25},{"hcp_hi":11,"hcp_lo":5,"target":22},{"hcp_hi":4,"hcp_lo":0,"target":19}]}'::jsonb, null),
('up-and-down-series', null, 'booklet', 'chipping', 'short', 'Up & Down Series', null, 20, 5, 'Chip & Putt', '{"de":"1 Ball"}'::jsonb, '{"de":{"setup":"Einen oder mehrere Schläger (E8 bis SW); Ziel in 4-20 m; Distanzen und Schwierigkeit variieren, Parcours-Verlauf beibehalten.","goal":"Möglichst viele Up & Downs in Serie.","procedure":"Droppen, chippen, zu Ende putten. Nur bei max. 2 Schlägen neues Ziel, sonst Situation wiederholen. Eingechippt = 1 Schlag gewonnen (einmal 2 Putts in der Serie erlaubt).","scoring_note":"Up & Downs in Serie: 54-36: 2 | 35-27: 3 | 26-19: 4 | 18-12: 5 | 11-5: 7 | 4-0: 9 (max. 20 Min, bestes Resultat)"},"en":null}'::jsonb, '{"type":"streak","lower_is_better":false,"perfect":null,"bands":[{"hcp_hi":54,"hcp_lo":36,"target":2},{"hcp_hi":35,"hcp_lo":27,"target":3},{"hcp_hi":26,"hcp_lo":19,"target":4},{"hcp_hi":18,"hcp_lo":12,"target":5},{"hcp_hi":11,"hcp_lo":5,"target":7},{"hcp_hi":4,"hcp_lo":0,"target":9}]}'::jsonb, null),
('beat-21', null, 'booklet', 'chipping', 'short', 'Beat 21', null, 20, 4, 'Chip & Putt', '{"de":"1 Ball"}'::jsonb, '{"de":{"setup":"Positionen in 6-12 m, von denen mind. 3 Löcher anspielbar sind; ggf. mit Tee markieren.","goal":"Möglichst oft Up & Down: 1 Chip + 1 Putt.","procedure":"11 Situationen; Ball droppen, nah an die Fahne chippen, zu Ende putten, Score notieren.","scoring_note":"Schläge: 54-36: 33 | 35-27: 30 | 26-19: 28 | 18-12: 26 | 11-5: 24 | 4-0: 21"},"en":null}'::jsonb, '{"type":"count_lower_better","lower_is_better":true,"perfect":11,"bands":[{"hcp_hi":54,"hcp_lo":36,"target":33},{"hcp_hi":35,"hcp_lo":27,"target":30},{"hcp_hi":26,"hcp_lo":19,"target":28},{"hcp_hi":18,"hcp_lo":12,"target":26},{"hcp_hi":11,"hcp_lo":5,"target":24},{"hcp_hi":4,"hcp_lo":0,"target":21}]}'::jsonb, null),
('draw-back', null, 'booklet', 'putting', 'putting', 'Draw Back', 'Alex Noren', 15, 6, 'Lange Putts', '{"de":"1 Ball"}'::jsonb, '{"de":{"setup":"9 Löcher, Reihenfolge beliebig, Entfernungen 5-20 m.","goal":"Möglichst wenige Putts für 9 Löcher.","procedure":"Bleibt der Ball innerhalb 1 Schlägerlänge hinter dem Loch: von dort einlochen. Außerhalb oder vor dem Loch: 1 Schlägerlänge zurücklegen. Jeder Fehlputt: erneut 1 Schlägerlänge zurück, bis der Ball fällt.","scoring_note":"Putts: 54-27: 27 | 26-12: 24 | 11-0: 20"},"en":null}'::jsonb, '{"type":"count_lower_better","lower_is_better":true,"perfect":9,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":27},{"hcp_hi":26,"hcp_lo":12,"target":24},{"hcp_hi":11,"hcp_lo":0,"target":20}]}'::jsonb, null),
('five-balls', null, 'booklet', 'putting', 'putting', 'Five Balls', 'Thomas Levet', 15, 4, 'Lange Putts', '{"de":"5 Bälle, 1 Tee, 1 Schläger"}'::jsonb, '{"de":{"setup":"Putt aus 7 m mit wenig Break; Schläger 50 cm hinter dem Loch quer zur Linie.","goal":"Möglichst oft 5 Punkte in einer Serie.","procedure":"Serie à 5 Bälle. Gelocht = 2 P; auf Lochhöhe oder im Korridor bis zum Schläger = 1 P; zu kurz oder Schläger berührt = -1 P. Nach 5 P Loch wechseln.","scoring_note":"Serien mit 5 P in 15 Min: 54-27: 1 | 26-12: 2 | 11-0: 3"},"en":null}'::jsonb, '{"type":"count_higher_better","lower_is_better":false,"perfect":null,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":1},{"hcp_hi":26,"hcp_lo":12,"target":2},{"hcp_hi":11,"hcp_lo":0,"target":3}]}'::jsonb, 'Ballanzahl (3 oder 5) auf Foto unscharf'),
('up-and-down-omeara', null, 'booklet', 'putting', 'putting', 'Up & Down', 'Mark O''Meara', 5, 2, 'Lange Putts', '{"de":"1 Ball, 5 Tees"}'::jsonb, '{"de":{"setup":"5 Positionen auf dem Vorgrün, max. 3 m vom Grün, mit Tee markieren.","goal":"Möglichst oft Up & Down, max. 2 Schläge pro Station.","procedure":"Von 5 Positionen (7-15 m zum Loch) je 1 Ball droppen und putten, Loch fertig spielen, Schläge zählen.","scoring_note":"Schläge: 54-27: 15 | 26-12: 12 | 11-0: 10"},"en":null}'::jsonb, '{"type":"count_lower_better","lower_is_better":true,"perfect":5,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":15},{"hcp_hi":26,"hcp_lo":12,"target":12},{"hcp_hi":11,"hcp_lo":0,"target":10}]}'::jsonb, 'Minutenangabe schwer lesbar'),
('pace-putting', null, 'booklet', 'putting', 'putting', 'Pace Putting', 'Danny Willett', 20, 5, 'Lange Putts', '{"de":"3 Bälle, 6 Tees"}'::jsonb, '{"de":{"setup":"Loch mit wenig/keinem Break; Tees bei 4,5 / 6 / 7,5 / 9 m; dazu Tee 30 cm vor und 60 cm hinter dem Loch (außerhalb der Puttlinie).","goal":"Möglichst viele Punkte sammeln.","procedure":"Je 3 Putts von allen 4 Positionen. Vor dem Loch innerhalb 30 cm = 1 P; innerhalb 60 cm hinter dem Loch = 2 P; gelocht = 3 P; außerhalb = -1 P.","scoring_note":"Punkte: 54-27: 8 | 26-12: 12 | 11-0: 21"},"en":null}'::jsonb, '{"type":"points_per_ball","lower_is_better":false,"perfect":36,"buttons":[3,2,1,-1],"bands":[{"hcp_hi":54,"hcp_lo":27,"target":8},{"hcp_hi":26,"hcp_lo":12,"target":12},{"hcp_hi":11,"hcp_lo":0,"target":21}]}'::jsonb, 'Minutenangabe schwer lesbar'),
('control-the-line', null, 'booklet', 'putting', 'putting', 'Control the Line', 'David Frost', 10, 4, 'Lange Putts', '{"de":"5-9 Bälle, 2 Tees"}'::jsonb, '{"de":{"setup":"Ziel/Loch in ca. 10 m ohne viel Break, mit Tee markiert; zweites Tee ca. 5 m vom Startpunkt.","goal":"Möglichst viele Bälle in eine Reihe spielen.","procedure":"1. Ball aufs Ziel = Referenz. Jeder weitere Ball muss kürzer als der vorherige liegen. Ende, wenn ein Ball länger ist oder die 5-m-Marke unterschreitet. Max. 3 Durchgänge.","scoring_note":"Bälle in Linie: 54-27: 5 | 26-12: 7 | 11-0: 9 (bestes aus max. 3)"},"en":null}'::jsonb, '{"type":"count_higher_better","lower_is_better":false,"perfect":null,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":5},{"hcp_hi":26,"hcp_lo":12,"target":7},{"hcp_hi":11,"hcp_lo":0,"target":9}]}'::jsonb, 'Minutenangabe schwer lesbar'),
('hit-the-hall', null, 'booklet', 'putting', 'putting', 'Hit the Hall', 'David Howell', 10, 4, 'Lange Putts', '{"de":"3 Bälle, 5 Tees, 3 Schläger, Stoppuhr"}'::jsonb, '{"de":{"setup":"Loch mit geradem Verlauf (10 m); 5 Tees im Abstand von 2 m auf einer Linie zum Loch (2/4/6/8/10 m); aus 3 Schlägern/Sticks Korridor 90 cm hinter dem Loch.","goal":"Lochen oder in den Korridor putten; erst mit 3 Punkten an einer Station eine Position weiter nach hinten.","procedure":"Je 3 Bälle pro Station, Start bei 2 m. Gelocht = 2 P, im Korridor = 1 P, vor dem Loch oder Schläger berührt = 0 P. Unter 3 P Station wiederholen. Ende bei 3 P von 10 m.","scoring_note":"Benötigte Putts: 54-27: 24 | 26-12: 18 | 11-0: 15 (nach 10 Min abbrechen, erreichte Station notieren)"},"en":null}'::jsonb, '{"type":"points_per_ball","lower_is_better":true,"perfect":15,"buttons":[2,1,0],"result_is_putts":true,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":24},{"hcp_hi":26,"hcp_lo":12,"target":18},{"hcp_hi":11,"hcp_lo":0,"target":15}]}'::jsonb, 'Titel laut Foto »Hit the Hall«'),
('around-the-world', null, 'booklet', 'putting', 'putting', 'Around the World', 'Stewart Cink', 10, 5, 'Kurze Putts', '{"de":"3 Bälle, 8 Tees, Stoppuhr"}'::jsonb, '{"de":{"setup":"Loch mit etwas Break; in allen 4 Himmelsrichtungen 90 cm und 120 cm abmessen, 8 Positionen mit Tees markieren.","goal":"Möglichst viele Putts in Folge aus allen 4 Himmelsrichtungen lochen.","procedure":"In max. 10 Min alle 8 Putts in Folge lochen; mit den kurzen (90 cm) beginnen, gegen den Uhrzeigersinn; danach die langen (120 cm). Fehlputt = von vorne.","scoring_note":"Bälle in Folge: 54-27: 5 | 26-12: 7 | 11-0: 8 (nach 10 Min Bestmarke notieren)"},"en":null}'::jsonb, '{"type":"streak","lower_is_better":false,"perfect":8,"bands":[{"hcp_hi":54,"hcp_lo":27,"target":5},{"hcp_hi":26,"hcp_lo":12,"target":7},{"hcp_hi":11,"hcp_lo":0,"target":8}]}'::jsonb, 'Uhr-Symbol evtl. 20 Min; Text nennt max. 10 Min'),
